function makeBall(stuck=true){ return { x: paddle.x+paddle.w/2, y: paddle.y-8, r:7, vx:0, vy:0, stuck }; }

function buildLevel(level){
  blocks = [];
  const cols=10, rows=Math.min(4+level, 8);
  const margin=40, top=70, gap=6;
  const bw=(W-margin*2-gap*(cols-1))/cols, bh=22;
  for(let r=0;r<rows;r++){
    for(let c=0;c<cols;c++){
      let hp=1;
      if(level>=2 && (r===0||Math.random()<0.15)) hp=2;
      blocks.push({x:margin+c*(bw+gap), y:top+r*(bh+gap), w:bw, h:bh, hp, maxhp:hp, color: ...});
    }
  }
}
